import React from "react";
import type { Meta, StoryObj } from "@storybook/react";
import { Close } from "@airbus/icons/react";
import withDarkMode from "../../lib/utils/storybookDecorators";
import Button from "../IconButton";
import IconButton from "../IconButton";
import ComboBox from "../ComboBox";
import Flex from "../Flex";
import Stack from "../Stack";
import Toggle from "../Toggle";
import Typography from "../Typography";
import Popover, { Popover as PopoverWithoutRef } from "./Popover";

const meta: Meta<typeof Popover> = {
  id: "Components/Popover",
  title: "Building Blocks/Popover",
  component: PopoverWithoutRef,
};

export default meta;
type Story = StoryObj<typeof Popover>;

export const Basic: Story = {
  tags: ["visual-test"],
  parameters: { docs: { source: { type: "code" } } },
  render: (args) => {
    const [btnNode, setBtnNode] = React.useState<HTMLElement | null>();
    const [open, setOpen] = React.useState(false);
    return (
      <>
        <Button
          ref={(node) => setBtnNode(node)}
          variant="primary"
          onClick={() => setOpen(true)}
        >
          Open
        </Button>
        <Popover referenceNode={btnNode} {...args} open={open}>
          <Flex
            className="w-288 p-1/2"
            justify="space-between"
            alignItems="center"
          >
            <Typography variant="medium">Example</Typography>
            <IconButton
              size="small"
              variant="ghost"
              aria-label="Close"
              onClick={() => setOpen(false)}
            >
              <Close />
            </IconButton>
          </Flex>
        </Popover>
      </>
    );
  },
};

export const Dark: Story = {
  ...Basic,
  tags: ["visual-test"],
  decorators: [withDarkMode],
  parameters: { docs: { source: { type: "dynamic" } } },
};

export const Placement: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const [btnNode, setBtnNode] = React.useState<HTMLElement | null>();
    const [open, setOpen] = React.useState(false);
    const [placement, setPlacement] = React.useState<any>("top");
    const placements = [
      "bottom-end",
      "bottom-start",
      "bottom",
      "left-end",
      "left-start",
      "left",
      "right-end",
      "right-start",
      "right",
      "top-end",
      "top-start",
      "top",
    ];

    return (
      <>
        <Stack spacing="2-x" className="w-208">
          <Button
            ref={(node) => setBtnNode(node)}
            variant="primary"
            onClick={() => setOpen(true)}
          >
            Open
          </Button>
          <ComboBox
            options={placements}
            value={placement}
            onChange={(val: any) => setPlacement(val)}
          ></ComboBox>
        </Stack>
        <Popover
          open={open}
          referenceNode={btnNode}
          placement={placement}
          fallbackPlacements={["top", "right"]}
        >
          <Flex
            className="w-288 p-1/2"
            justify="space-between"
            alignItems="center"
          >
            <Typography variant="medium">Example</Typography>
            <IconButton
              variant="ghost"
              aria-label="Close"
              onClick={() => setOpen(false)}
            >
              <Close />
            </IconButton>
          </Flex>
        </Popover>
      </>
    );
  },
};

export const Arrow: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const [btnNode, setBtnNode] = React.useState<HTMLElement | null>();
    const [open, setOpen] = React.useState(false);
    const [hidden, setHidden] = React.useState(false);
    const [custom, setCustom] = React.useState(false);
    return (
      <>
        <Stack spacing="2-x">
          <Button
            ref={(node) => setBtnNode(node)}
            variant="primary"
            onClick={() => setOpen(true)}
          >
            Open
          </Button>
          <Toggle
            label="Hide"
            checked={hidden}
            onChange={(_, val) => setHidden(val)}
          />
          <Toggle
            label="Custom"
            checked={custom}
            onChange={(_, val) => setCustom(val)}
          />
        </Stack>
        <Popover
          placement="top"
          open={open}
          referenceNode={btnNode}
          arrow={!hidden}
          arrowClassName={custom ? "custom-tooltip-arrow" : ""}
        >
          <Flex
            className="w-288 p-1/2"
            justify="space-between"
            alignItems="center"
          >
            <Typography variant="h5">Example</Typography>
            <IconButton
              variant="ghost"
              aria-label="Close"
              onClick={() => setOpen(false)}
            >
              <Close />
            </IconButton>
          </Flex>
        </Popover>
      </>
    );
  },
};

export const Offset: Story = {
  ...Basic,
  parameters: { docs: { source: { type: "dynamic" } } },
  args: {
    placement: "top-end",
    offset: [50, 25],
  },
};
